def _q(b: int, n: int, d: str, p: str, c: str, w: list[str], e: str, h: str = '', fig=None):
    return make_q(f'LSDL5-B{b:02d}-{n:03d}', d, p, c, w, e, 'Lịch sử và Địa lí 5', h, fig)

